import { spawn, spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { lstatSync, mkdirSync, readFileSync, realpathSync, rmdirSync, unlinkSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import path from "node:path";

// The label is generated by the privileged supervisor, never by the caller.
// Only transient containers created for this particular operation may carry it.
const LABEL = "org.aurion.schema-apply-operation";
const self = fileURLToPath(import.meta.url);
const pause = ms => new Promise(resolve => setTimeout(resolve, ms));

function groupExists(pid) {
  try { process.kill(-pid, 0); return true; }
  catch (error) { if (error.code === "ESRCH") return false; throw error; }
}

function startTime(pid) {
  try {
    const stat = readFileSync(`/proc/${pid}/stat`, "utf8");
    const end = stat.lastIndexOf(") ");
    if (end < 0) throw new Error("LIFECYCLE_PROC_STAT_INVALID");
    const start = stat.slice(end + 2).split(" ")[19];
    if (!/^[0-9]+$/.test(start ?? "")) throw new Error("LIFECYCLE_PROC_STAT_INVALID");
    return start;
  } catch (error) { if (error.code === "ENOENT") return null; throw error; }
}

function signalGroup(pid, expectedStart, signal) {
  const actual = startTime(pid);
  if (actual !== null && actual !== expectedStart) throw new Error("LIFECYCLE_PID_REUSED");
  try { process.kill(-pid, signal); }
  catch (error) { if (error.code !== "ESRCH") throw error; }
}

function containers(operation) {
  const result = spawnSync("docker", ["ps", "-aq", "--no-trunc", "--filter", `label=${LABEL}=${operation}`], { encoding: "utf8", timeout: 5000 });
  if (result.status !== 0 || result.error) throw new Error("LIFECYCLE_DOCKER_READBACK_FAILED");
  const ids = result.stdout.trim().split(/\s+/).filter(Boolean);
  if (ids.some(id => !/^[a-f0-9]{64}$/.test(id))) throw new Error("LIFECYCLE_CONTAINER_ID_INVALID");
  return ids;
}

function removeContainers(operation) {
  for (const id of containers(operation)) {
    // A concurrent normal exit may already have removed a --rm container.
    spawnSync("docker", ["rm", "-fv", id], { stdio: "ignore", timeout: 10000 });
  }
  return containers(operation).length === 0;
}

function clearFence(fence, operation) {
  if (readFileSync(path.join(fence, "operation"), "utf8") !== operation) throw new Error("LIFECYCLE_FENCE_IDENTITY_MISMATCH");
  unlinkSync(path.join(fence, "operation"));
  rmdirSync(fence);
}

async function terminateAndClean(pid, expectedStart, operation, fence) {
  // Stop the shell and its Docker clients first; the daemon's processes are
  // independent, so remove only containers carrying this operation's label.
  signalGroup(pid, expectedStart, "SIGTERM");
  await pause(250);
  signalGroup(pid, expectedStart, "SIGKILL");
  let consecutiveEmpty = 0;
  for (let attempt = 0; attempt < 60; attempt += 1) {
    try {
      signalGroup(pid, expectedStart, "SIGKILL");
      const empty = removeContainers(operation);
      consecutiveEmpty = empty && !groupExists(pid) ? consecutiveEmpty + 1 : 0;
      if (consecutiveEmpty >= 3) {
        clearFence(fence, operation);
        return true;
      }
    } catch { consecutiveEmpty = 0; }
    await pause(500);
  }
  // Keep the durable fence if cleanup cannot be independently confirmed.
  return false;
}

async function reap(pid, expectedStart, operation, fence) {
  let stopping = false;
  const stop = async () => {
    if (stopping) return;
    stopping = true;
    const clean = await terminateAndClean(pid, expectedStart, operation, fence).catch(() => false);
    process.exit(clean ? 0 : 1);
  };
  process.stdin.on("data", stop); // Extra bytes are not a valid lease.
  process.stdin.on("end", stop);
  process.stdin.on("error", stop);
  process.stdin.resume();
  process.on("disconnect", stop);
  process.on("message", message => {
    if (message === "abort") void stop();
    else if (message === "finished" && !stopping) process.exit(0);
  });
  process.send?.("ready");
}

/** Supervise a process group and its labelled Docker containers.
 * The injectable command/state directory are for the isolated regression
 * harness. The privileged CLI below supplies only fixed production paths.
 */
export async function supervise({ command, args, stateDir }) {
  mkdirSync(stateDir, { recursive: true, mode: 0o700 });
  const directory = lstatSync(stateDir);
  if (!directory.isDirectory() || directory.uid !== process.getuid?.() || (directory.mode & 0o077) !== 0 || realpathSync(stateDir) !== stateDir) throw new Error("LIFECYCLE_STATE_DIRECTORY_UNSAFE");
  const operation = randomBytes(16).toString("hex");
  const fence = path.join(stateDir, ".active-operation");
  mkdirSync(fence, { mode: 0o700 }); // EEXIST fails closed, including after a crash.
  writeFileSync(path.join(fence, "operation"), operation, { mode: 0o600, flag: "wx" });
  const child = spawn("bash", ["-c", 'IFS= read -r gate && [[ "$gate" == GO ]] || exit 125; exec "$@"', "aurion-schema-gate", command, ...args], {
    detached: true,
    env: { ...process.env, AURION_SCHEMA_APPLY_OPERATION: operation },
    stdio: ["pipe", "inherit", "inherit"],
  });
  if (!child.pid) throw new Error("LIFECYCLE_WORKER_START_FAILED");
  const expectedStart = startTime(child.pid);
  if (expectedStart === null) throw new Error("LIFECYCLE_WORKER_IDENTITY_UNAVAILABLE");
  const reaper = spawn(process.execPath, [self, "--reaper", String(child.pid), expectedStart, operation, fence], {
    detached: true, stdio: [0, "ignore", "ignore", "ipc"],
  });
  let cancelled = false;
  let stopping = false;
  const abort = () => {
    if (stopping) return;
    cancelled = true;
    try { signalGroup(child.pid, expectedStart, "SIGTERM"); } catch {}
    if (reaper.connected) reaper.send("abort");
  };
  process.stdin.on("data", abort);
  process.stdin.on("end", abort);
  process.stdin.on("error", abort);
  process.stdin.resume();
  process.on("SIGINT", abort);
  process.on("SIGTERM", abort);
  const reaperExit = new Promise(resolve => reaper.once("exit", (code, signal) => resolve({ code, signal })));
  const childExit = new Promise(resolve => child.once("exit", (code, signal) => resolve({ code, signal })));
  let fallbackCleanup = null;
  void reaperExit.then(result => {
    if (!stopping) {
      abort();
      if (result.code !== 0) fallbackCleanup = terminateAndClean(child.pid, expectedStart, operation, fence).catch(() => false);
    }
  });
  const ready = await Promise.race([
    new Promise(resolve => reaper.once("message", value => resolve(value === "ready"))),
    reaperExit.then(() => false),
    new Promise(resolve => { const timer = setTimeout(() => resolve(false), 5000); timer.unref(); }),
  ]);
  if (!ready || cancelled) abort();
  else child.stdin.end("GO\n");
  const childResult = await childExit;
  if (!cancelled) {
    try {
      if (groupExists(child.pid) || containers(operation).length !== 0) abort();
    } catch { abort(); }
  }
  if (cancelled) {
    if (reaper.connected) reaper.send("abort");
    stopping = true;
    const result = await reaperExit;
    if (fallbackCleanup || result.code !== 0) {
      const clean = fallbackCleanup ? await fallbackCleanup : await terminateAndClean(child.pid, expectedStart, operation, fence).catch(() => false);
      if (!clean) process.stderr.write("Schema operation cleanup not verified; active fence retained.\n");
    }
    process.stdin.pause();
    process.stdin.unref?.();
    return 125;
  }
  stopping = true;
  if (reaper.connected) reaper.send("finished");
  const result = await reaperExit;
  if (result.code !== 0) {
    process.stdin.pause();
    process.stdin.unref?.();
    return 125;
  }
  clearFence(fence, operation);
  process.stdin.pause();
  process.stdin.unref?.();
  return childResult.code ?? 125;
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  if (process.argv[2] === "--reaper") {
    const [, , , pidText, expectedStart, operation, fence] = process.argv;
    if (!/^[1-9][0-9]*$/.test(pidText ?? "") || !/^[0-9]+$/.test(expectedStart ?? "") || !/^[a-f0-9]{32}$/.test(operation ?? "") || path.basename(fence ?? "") !== ".active-operation") process.exit(64);
    await reap(Number(pidText), expectedStart, operation, fence);
  } else {
    const [, , expectedSha, planSha256] = process.argv;
    if (process.getuid?.() !== 0 || process.argv.length !== 4 || !/^[a-f0-9]{40}$/.test(expectedSha ?? "") || !/^[a-f0-9]{64}$/.test(planSha256 ?? "")) process.exit(64);
    try {
      process.exitCode = await supervise({
        command: `/opt/echoes-of-aurion-schema-apply/releases/${expectedSha}/deploy/aurion-production-schema-apply-core`,
        args: [expectedSha, planSha256],
        stateDir: "/var/lib/echoes-of-aurion/schema-apply",
      });
    } catch {
      process.stderr.write("Schema operation lifecycle failed or is already fenced.\n");
      process.exitCode = 125;
    }
  }
}
